def act(obs, state):
    """
    Hybrid policy combining best ideas from both parents.
    - Compact cluster with vertical wire spine + flanking roads
    - Balanced zone placement (R/C/I)
    - Second power plant for growth
    - Services at appropriate thresholds
    """
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    def in_bounds(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    # Fixed anchor: place first coal plant at (58, 50)
    if not np.any(pm):
        return (Tool.COALPOWER, 58, 50)

    plant_ys, plant_xs = np.where(pm)
    # Primary plant center
    px = int(plant_xs[0]) if len(plant_xs) > 0 else 58
    py = int(plant_ys[0]) if len(plant_ys) > 0 else 50

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = res_count + com_count + ind_count

    def pick_tool():
        t = max(total_zones, 1)
        i_r = ind_count / t
        c_r = com_count / t
        if i_r < 0.22:
            return Tool.INDUSTRIAL
        if c_r < 0.25:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    # Wire spine column: just right of plant
    wire_col = px + 2
    # Road columns flanking the wire spine
    road_col_l = wire_col - 1
    road_col_r = wire_col + 1

    # Determine vertical extent of wire spine based on population
    pop_factor = min(30, obs.city_pop // 15)
    spine_top = max(3, py - 14 - pop_factor)
    spine_bot = min(WORLD_H - 4, py + 14 + pop_factor)

    # --- Build vertical wire spine ---
    wire_in_col = [r for r in range(WORLD_H)
                   if 0 <= wire_col < WORLD_W and bool(wm[r, wire_col])]

    if not wire_in_col:
        # Seed wire adjacent to plant
        for dy in range(-2, 3):
            ny = py + dy
            if in_bounds(wire_col, ny) and (bool(em[ny, wire_col]) or bool(wm[ny, wire_col])) and not bool(pm[ny, wire_col]):
                return (Tool.WIRE, wire_col, ny)
    else:
        min_wr = min(wire_in_col)
        max_wr = max(wire_in_col)
        # Grow downward
        if max_wr < spine_bot:
            nr = max_wr + 1
            if in_bounds(wire_col, nr) and (bool(em[nr, wire_col]) or bool(wm[nr, wire_col])) and not bool(pm[nr, wire_col]):
                return (Tool.WIRE, wire_col, nr)
        # Grow upward
        if min_wr > spine_top:
            nr = min_wr - 1
            if in_bounds(wire_col, nr) and (bool(em[nr, wire_col]) or bool(wm[nr, wire_col])) and not bool(pm[nr, wire_col]):
                return (Tool.WIRE, wire_col, nr)

    # --- Build road columns flanking the wire spine ---
    # For each wire row, ensure road on left and right
    if wire_in_col:
        step_mod3 = obs.step % 3
        rows_to_check = wire_in_col[::2] if step_mod3 < 2 else wire_in_col[1::2]
        for wr in rows_to_check:
            if in_bounds(road_col_l, wr) and bool(em[wr, road_col_l]) and not bool(pm[wr, road_col_l]):
                return (Tool.ROAD, road_col_l, wr)
            if in_bounds(road_col_r, wr) and bool(em[wr, road_col_r]) and not bool(pm[wr, road_col_r]):
                return (Tool.ROAD, road_col_r, wr)

    # --- Second power plant when city grows ---
    if total_zones > 8 or obs.city_pop > 200:
        p2x = px + 20
        p2y = py
        if in_bounds(p2x, p2y):
            nearby_plant = any(
                in_bounds(p2x + dx, p2y + dy) and bool(pm[p2y + dy, p2x + dx])
                for dy in range(-5, 6) for dx in range(-5, 6)
                if in_bounds(p2x + dx, p2y + dy)
            )
            if not nearby_plant and bool(em[p2y, p2x]):
                return (Tool.COALPOWER, p2x, p2y)
            # Wire horizontal bridge from spine to second plant
            if not nearby_plant:
                for wc in range(wire_col + 1, p2x - 1):
                    if in_bounds(wc, py) and bool(em[py, wc]) and not bool(pm[py, wc]):
                        return (Tool.WIRE, wc, py)
            # Second vertical wire spine
            wire_col2 = p2x - 2
            if wire_in_col:
                for wr in wire_in_col:
                    if in_bounds(wire_col2, wr) and bool(em[wr, wire_col2]) and not bool(pm[wr, wire_col2]):
                        return (Tool.WIRE, wire_col2, wr)

    # --- Build proximity masks for zone placement ---
    nbr_road = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-2, 3):
        for dx in range(-2, 3):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
            nbr_road[r0:r1, c0:c1] |= rm[sr0:sr1, sc0:sc1]

    nbr_wire = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-7, 8):
        for dx in range(-7, 8):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
            nbr_wire[r0:r1, c0:c1] |= wm[sr0:sr1, sc0:sc1]
            nbr_wire[r0:r1, c0:c1] |= pm[sr0:sr1, sc0:sc1]

    zone_tiles = resm | comm | indm

    def zone_clear(zx, zy):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                nr2, nc2 = zy + dr, zx + dc
                if not in_bounds(nc2, nr2):
                    return False
                if not bool(em[nr2, nc2]) and not bool(zone_tiles[nr2, nc2]):
                    return False
        return True

    # --- Place zones near roads and power ---
    cand_mask = em & nbr_road & nbr_wire
    cand_mask[0:2, :] = False
    cand_mask[WORLD_H-2:, :] = False
    cand_mask[:, 0:2] = False
    cand_mask[:, WORLD_W-2:] = False

    cys, cxs = np.where(cand_mask)
    if len(cxs) > 0:
        # Prioritize candidates near wire column
        dists = np.abs(cxs - wire_col) + np.abs(cys - py) // 3
        order = np.argsort(dists)
        step_off = int(obs.step * 7) % max(len(order), 1)
        checked = 0
        for i in range(len(order)):
            k = order[(step_off + i) % len(order)]
            zx, zy = int(cxs[k]), int(cys[k])
            if zone_clear(zx, zy):
                return (pick_tool(), zx, zy)
            checked += 1
            if checked > 80:
                break

    # --- Extend roads near wire to fill gaps ---
    road_ys2, road_xs2 = np.where(rm)
    if len(road_xs2) > 0:
        step_k = int(obs.step * 11) % max(len(road_xs2), 1)
        for offset in range(min(len(road_xs2), 20)):
            k = (step_k + offset * 7) % len(road_xs2)
            rx2, ry2 = int(road_xs2[k]), int(road_ys2[k])
            for dx2, dy2 in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                nx2, ny2 = rx2 + dx2, ry2 + dy2
                if in_bounds(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]) and bool(nbr_wire[ny2, nx2]):
                    return (Tool.ROAD, nx2, ny2)

    # --- Services when pop is high enough ---
    if obs.city_pop > 150:
        for fpos in [(px - 10, py - 10), (px + 10, py - 10)]:
            fsx, fsy = fpos
            if in_bounds(fsx, fsy) and bool(em[fsy, fsx]):
                return (Tool.FIRESTATION, fsx, fsy)
    if obs.city_pop > 350:
        for ppos in [(px - 10, py + 10), (px + 10, py + 10)]:
            psx, psy = ppos
            if in_bounds(psx, psy) and bool(em[psy, psx]):
                return (Tool.POLICESTATION, psx, psy)

    # --- Expand wire laterally as fallback ---
    wire_ys_arr, wire_xs_arr = np.where(wm)
    if len(wire_xs_arr) > 0:
        step_k2 = int(obs.step * 13) % max(len(wire_xs_arr), 1)
        for offset in range(min(len(wire_xs_arr), 15)):
            k = (step_k2 + offset * 5) % len(wire_xs_arr)
            wx2, wy2 = int(wire_xs_arr[k]), int(wire_ys_arr[k])
            for dx3, dy3 in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                nx3, ny3 = wx2 + dx3, wy2 + dy3
                if in_bounds(nx3, ny3) and bool(em[ny3, nx3]) and not bool(pm[ny3, nx3]):
                    return (Tool.WIRE, nx3, ny3)

    return None

# Multi-neighborhood closed-loop policy
# Strategy: Build multiple power plant clusters across the map,
# each with its own wire spine and flanking roads, zones densely packed.

def init(obs, state):
    """Bootstrap: place first coal plant and seed wires/roads."""
    actions = []
    # Primary plant at center-left
    actions.append((Tool.COALPOWER, 30, 50))
    # Seed wire upward and downward
    for dy in range(-2, 3):
        actions.append((Tool.WIRE, 32, 50 + dy))
    # Seed roads flanking wire
    for dy in range(-2, 3):
        actions.append((Tool.ROAD, 31, 50 + dy))
        actions.append((Tool.ROAD, 33, 50 + dy))
    return actions


def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    pop = obs.city_pop
    step = obs.step
    total_steps = obs.n_steps

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = res_count + com_count + ind_count

    # ---- PHASE MANAGEMENT ----
    # We define multiple "neighborhood anchors" spread across the map
    # Each anchor: (plant_x, plant_y, wire_col, road_l, road_r)
    anchors = [
        (30, 50, 32, 31, 33),   # left-center
        (60, 50, 62, 61, 63),   # center
        (90, 50, 92, 91, 93),   # right-center
        (30, 25, 32, 31, 33),   # left-top
        (60, 25, 62, 61, 63),   # center-top
        (90, 25, 92, 91, 93),   # right-top
        (30, 75, 32, 31, 33),   # left-bottom
        (60, 75, 62, 61, 63),   # center-bottom
        (90, 75, 92, 91, 93),   # right-bottom
    ]

    # Unlock anchors progressively as city grows
    def num_active_anchors():
        if pop < 100:
            return 1
        elif pop < 400:
            return 2
        elif pop < 800:
            return 3
        elif pop < 1500:
            return 5
        elif pop < 3000:
            return 7
        else:
            return 9

    active_anchors = anchors[:num_active_anchors()]

    # ---- ENSURE POWER PLANTS ----
    for (px, py, wc, rl, rr) in active_anchors:
        # Check if plant exists near anchor
        has_plant = any(
            ib(px + dx, py + dy) and bool(pm[py + dy, px + dx])
            for dx in range(-3, 4) for dy in range(-3, 4)
            if ib(px + dx, py + dy)
        )
        if not has_plant:
            if ib(px, py) and bool(em[py, px]):
                return (Tool.COALPOWER, px, py)
            # Try nearby empty spot
            for r in range(1, 8):
                for dy2 in range(-r, r + 1):
                    for dx2 in range(-r, r + 1):
                        nx, ny = px + dx2, py + dy2
                        if ib(nx, ny) and bool(em[ny, nx]):
                            return (Tool.COALPOWER, nx, ny)

    # ---- WIRE SPINE BUILDING ----
    # For each active anchor, extend vertical wire spine
    pop_factor = min(35, pop // 10)
    for (px, py, wc, rl, rr) in active_anchors:
        if not ib(wc, py):
            continue
        spine_top = max(2, py - 16 - pop_factor)
        spine_bot = min(WORLD_H - 3, py + 16 + pop_factor)

        # Extend wire spine
        wire_in_col = [r for r in range(WORLD_H) if ib(wc, r) and bool(wm[r, wc])]

        if not wire_in_col:
            # Seed wire near plant
            for dy2 in range(-3, 4):
                ny = py + dy2
                if ib(wc, ny) and bool(em[ny, wc]) and not bool(pm[ny, wc]):
                    return (Tool.WIRE, wc, ny)
        else:
            min_wr = min(wire_in_col)
            max_wr = max(wire_in_col)
            if max_wr < spine_bot:
                nr = max_wr + 1
                if ib(wc, nr) and (bool(em[nr, wc]) or bool(wm[nr, wc])) and not bool(pm[nr, wc]):
                    return (Tool.WIRE, wc, nr)
            if min_wr > spine_top:
                nr = min_wr - 1
                if ib(wc, nr) and (bool(em[nr, wc]) or bool(wm[nr, wc])) and not bool(pm[nr, wc]):
                    return (Tool.WIRE, wc, nr)

    # ---- HORIZONTAL WIRE CONNECTIONS between anchors ----
    # Connect wire spines horizontally at anchor Y levels for power sharing
    for i in range(len(active_anchors) - 1):
        px1, py1, wc1, _, _ = active_anchors[i]
        px2, py2, wc2, _, _ = active_anchors[i + 1]
        if py1 == py2:  # Same row anchors
            min_wc = min(wc1, wc2)
            max_wc = max(wc1, wc2)
            for cx in range(min_wc, max_wc + 1):
                if ib(cx, py1) and bool(em[py1, cx]) and not bool(pm[py1, cx]):
                    return (Tool.WIRE, cx, py1)

    # ---- ROAD BUILDING flanking wire spines ----
    for (px, py, wc, rl, rr) in active_anchors:
        wire_in_col = [r for r in range(WORLD_H) if ib(wc, r) and bool(wm[r, wc])]
        if not wire_in_col:
            continue
        # Build roads on both sides
        cycle = step % 4
        for wr in wire_in_col[cycle::4]:
            if ib(rl, wr) and bool(em[wr, rl]) and not bool(pm[wr, rl]):
                return (Tool.ROAD, rl, wr)
            if ib(rr, wr) and bool(em[wr, rr]) and not bool(pm[wr, rr]):
                return (Tool.ROAD, rr, wr)

    # ---- ZONE PLACEMENT ----
    zone_tiles = resm | comm | indm

    def pick_tool():
        t = max(total_zones, 1)
        i_r = ind_count / t
        c_r = com_count / t
        if i_r < 0.20:
            return Tool.INDUSTRIAL
        if c_r < 0.22:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    def zone_clear(zx, zy):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                nr2, nc2 = zy + dr, zx + dc
                if not ib(nc2, nr2):
                    return False
                if not bool(em[nr2, nc2]) and not bool(zone_tiles[nr2, nc2]):
                    return False
        return True

    # Compute neighbor road and wire masks
    nbr_road = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy2 in range(-2, 3):
        for dx2 in range(-2, 3):
            sr0 = max(0, -dy2); sr1 = min(WORLD_H, WORLD_H - dy2)
            sc0 = max(0, -dx2); sc1 = min(WORLD_W, WORLD_W - dx2)
            r0 = max(0, dy2); r1 = min(WORLD_H, WORLD_H + dy2)
            c0 = max(0, dx2); c1 = min(WORLD_W, WORLD_W + dx2)
            nbr_road[r0:r1, c0:c1] |= rm[sr0:sr1, sc0:sc1]

    nbr_wire = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy2 in range(-8, 9):
        for dx2 in range(-8, 9):
            sr0 = max(0, -dy2); sr1 = min(WORLD_H, WORLD_H - dy2)
            sc0 = max(0, -dx2); sc1 = min(WORLD_W, WORLD_W - dx2)
            r0 = max(0, dy2); r1 = min(WORLD_H, WORLD_H + dy2)
            c0 = max(0, dx2); c1 = min(WORLD_W, WORLD_W + dx2)
            nbr_wire[r0:r1, c0:c1] |= wm[sr0:sr1, sc0:sc1]
            nbr_wire[r0:r1, c0:c1] |= pm[sr0:sr1, sc0:sc1]

    cand_mask = em & nbr_road & nbr_wire
    cand_mask[0:2, :] = False
    cand_mask[WORLD_H - 2:, :] = False
    cand_mask[:, 0:2] = False
    cand_mask[:, WORLD_W - 2:] = False

    cys, cxs = np.where(cand_mask)
    if len(cxs) > 0:
        # Prioritize candidates near active anchor wire columns
        best_dist = np.full(len(cxs), 999999, dtype=float)
        for (px, py, wc, rl, rr) in active_anchors:
            d = np.abs(cxs - wc) + np.abs(cys - py)
            best_dist = np.minimum(best_dist, d)
        order = np.argsort(best_dist)
        step_off = (step * 7) % max(len(order), 1)
        checked = 0
        for i in range(len(order)):
            k = order[(step_off + i) % len(order)]
            zx, zy = int(cxs[k]), int(cys[k])
            if zone_clear(zx, zy):
                return (pick_tool(), zx, zy)
            checked += 1
            if checked > 100:
                break

    # ---- EXTEND ROADS from existing roads near wire ----
    road_ys2, road_xs2 = np.where(rm)
    if len(road_xs2) > 0:
        step_k = (step * 11) % max(len(road_xs2), 1)
        for offset in range(min(len(road_xs2), 30)):
            k = (step_k + offset * 7) % len(road_xs2)
            rx2, ry2 = int(road_xs2[k]), int(road_ys2[k])
            for dx2, dy2 in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                nx2, ny2 = rx2 + dx2, ry2 + dy2
                if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]) and bool(nbr_wire[ny2, nx2]):
                    return (Tool.ROAD, nx2, ny2)

    # ---- CIVIC SERVICES ----
    if pop > 300:
        svc_spots = [
            (45, 50), (75, 50), (45, 25), (75, 25),
            (45, 75), (75, 75), (20, 50), (100, 50)
        ]
        for (sx, sy) in svc_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.FIRESTATION, sx, sy)
    if pop > 800:
        pstations = [
            (45, 38), (75, 38), (45, 62), (75, 62),
            (20, 35), (100, 35), (20, 65), (100, 65)
        ]
        for (sx, sy) in pstations:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.POLICESTATION, sx, sy)
    if pop > 1500:
        stadiums = [(55, 15), (55, 85), (20, 50), (100, 50)]
        for (sx, sy) in stadiums:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.STADIUM, sx, sy)

    # ---- FALLBACK: extend wire laterally ----
    wire_ys_arr, wire_xs_arr = np.where(wm)
    if len(wire_xs_arr) > 0:
        step_k2 = (step * 13) % max(len(wire_xs_arr), 1)
        for offset in range(min(len(wire_xs_arr), 20)):
            k = (step_k2 + offset * 5) % len(wire_xs_arr)
            wx2, wy2 = int(wire_xs_arr[k]), int(wire_ys_arr[k])
            for dx3, dy3 in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                nx3, ny3 = wx2 + dx3, wy2 + dy3
                if ib(nx3, ny3) and bool(em[ny3, nx3]) and not bool(pm[ny3, nx3]):
                    return (Tool.WIRE, nx3, ny3)

    return None

# Multi-neighborhood city with 3 power plants, horizontal road arteries,
# and a denser zone mix spread across the map.

def init(obs, state):
    """Bootstrap: place 3 coal plants + connecting wires + seed roads"""
    actions = []
    # Plant 1: left cluster center
    actions.append((Tool.COALPOWER, 25, 50))
    # Plant 2: center cluster
    actions.append((Tool.COALPOWER, 60, 50))
    # Plant 3: right cluster
    actions.append((Tool.COALPOWER, 95, 50))
    # Horizontal wire spine connecting all plants at row 50
    for x in range(27, 59):
        actions.append((Tool.WIRE, x, 50))
    for x in range(62, 94):
        actions.append((Tool.WIRE, x, 50))
    # Seed vertical wire spines for each cluster
    for y in range(44, 57):
        actions.append((Tool.WIRE, 25, y))
        actions.append((Tool.WIRE, 60, y))
        actions.append((Tool.WIRE, 95, y))
    # Seed horizontal roads above and below wire spine for each cluster
    for x in range(20, 35):
        actions.append((Tool.ROAD, x, 47))
        actions.append((Tool.ROAD, x, 53))
    for x in range(55, 70):
        actions.append((Tool.ROAD, x, 47))
        actions.append((Tool.ROAD, x, 53))
    for x in range(90, 105):
        actions.append((Tool.ROAD, x, 47))
        actions.append((Tool.ROAD, x, 53))
    return actions


def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    def in_bounds(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    # Cluster definitions: (center_x, center_y, wire_col, road_rows)
    clusters = [
        {'cx': 25, 'cy': 50, 'wc': 25, 'roads': [47, 53]},
        {'cx': 60, 'cy': 50, 'wc': 60, 'roads': [47, 53]},
        {'cx': 95, 'cy': 50, 'wc': 95, 'roads': [47, 53]},
    ]

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = res_count + com_count + ind_count

    def pick_tool():
        t = max(total_zones, 1)
        i_r = ind_count / t
        c_r = com_count / t
        # Target: 30% industrial, 30% commercial, 40% residential
        if i_r < 0.28:
            return Tool.INDUSTRIAL
        if c_r < 0.28:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    # ---- Ensure all 3 plants exist ----
    plant_positions = [(25, 50), (60, 50), (95, 50)]
    for px, py in plant_positions:
        # Check if plant exists nearby (within 2 tiles)
        plant_there = False
        for dy in range(-2, 3):
            for dx in range(-2, 3):
                nx, ny = px + dx, py + dy
                if in_bounds(nx, ny) and bool(pm[ny, nx]):
                    plant_there = True
                    break
            if plant_there:
                break
        if not plant_there:
            if in_bounds(px, py):
                return (Tool.COALPOWER, px, py)

    # ---- Extend wire spines vertically for each cluster ----
    pop_factor = min(20, obs.city_pop // 20)
    spine_extent = 12 + pop_factor  # how far above/below center

    for cl in clusters:
        wc = cl['wc']
        cy = cl['cy']
        spine_top = max(3, cy - spine_extent)
        spine_bot = min(WORLD_H - 4, cy + spine_extent)

        wire_rows = [r for r in range(WORLD_H) if in_bounds(wc, r) and bool(wm[r, wc])]
        if not wire_rows:
            # seed wire adjacent to plant
            for dy in range(-2, 3):
                ny = cy + dy
                if in_bounds(wc, ny) and not bool(pm[ny, wc]):
                    return (Tool.WIRE, wc, ny)
        else:
            min_wr = min(wire_rows)
            max_wr = max(wire_rows)
            if max_wr < spine_bot:
                nr = max_wr + 1
                if in_bounds(wc, nr) and not bool(pm[nr, wc]):
                    return (Tool.WIRE, wc, nr)
            if min_wr > spine_top:
                nr = min_wr - 1
                if in_bounds(wc, nr) and not bool(pm[nr, wc]):
                    return (Tool.WIRE, wc, nr)

    # ---- Horizontal wire bridge between clusters ----
    # Connect cluster 1 to 2
    for x in range(27, 59):
        if in_bounds(x, 50) and bool(em[50, x]) and not bool(pm[50, x]):
            return (Tool.WIRE, x, 50)
    # Connect cluster 2 to 3
    for x in range(62, 94):
        if in_bounds(x, 50) and bool(em[50, x]) and not bool(pm[50, x]):
            return (Tool.WIRE, x, 50)

    # ---- Road arteries for each cluster ----
    for cl in clusters:
        wc = cl['wc']
        cy = cl['cy']
        wire_rows = [r for r in range(WORLD_H) if in_bounds(wc, r) and bool(wm[r, wc])]
        if not wire_rows:
            continue
        # Extend roads parallel to wire spine at offsets -1 and +1
        for road_col_offset in [-1, 1]:
            rc = wc + road_col_offset
            for wr in wire_rows:
                if in_bounds(rc, wr) and bool(em[wr, rc]) and not bool(pm[wr, rc]):
                    return (Tool.ROAD, rc, wr)

        # Horizontal roads crossing wire at multiple rows
        spine_top = max(3, cy - min(20, obs.city_pop // 20 + 12))
        spine_bot = min(WORLD_H - 4, cy + min(20, obs.city_pop // 20 + 12))
        # Roads every 6 rows across a wider x range
        for wr in range(spine_top, spine_bot + 1, 6):
            x_lo = max(3, wc - 10)
            x_hi = min(WORLD_W - 4, wc + 10)
            for rx in range(x_lo, x_hi + 1):
                if in_bounds(rx, wr) and bool(em[wr, rx]) and not bool(pm[wr, rx]):
                    return (Tool.ROAD, rx, wr)

    # ---- Build proximity masks ----
    nbr_road = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-2, 3):
        for dx in range(-2, 3):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
            nbr_road[r0:r1, c0:c1] |= rm[sr0:sr1, sc0:sc1]

    nbr_wire = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-6, 7):
        for dx in range(-6, 7):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
            nbr_wire[r0:r1, c0:c1] |= wm[sr0:sr1, sc0:sc1]
            nbr_wire[r0:r1, c0:c1] |= pm[sr0:sr1, sc0:sc1]

    zone_tiles = resm | comm | indm

    def zone_clear(zx, zy):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                nr2, nc2 = zy + dr, zx + dc
                if not in_bounds(nc2, nr2):
                    return False
                if not bool(em[nr2, nc2]) and not bool(zone_tiles[nr2, nc2]):
                    return False
        return True

    # ---- Place zones near roads and power ----
    cand_mask = em & nbr_road & nbr_wire
    cand_mask[0:2, :] = False
    cand_mask[WORLD_H-2:, :] = False
    cand_mask[:, 0:2] = False
    cand_mask[:, WORLD_W-2:] = False

    cys_arr, cxs_arr = np.where(cand_mask)
    if len(cxs_arr) > 0:
        # Prioritize candidates near any cluster center
        min_dist = np.full(len(cxs_arr), 999999.0)
        for cl in clusters:
            d = np.abs(cxs_arr - cl['cx']) + np.abs(cys_arr - cl['cy'])
            min_dist = np.minimum(min_dist, d)
        order = np.argsort(min_dist)
        step_off = int(obs.step * 7) % max(len(order), 1)
        checked = 0
        for i in range(len(order)):
            k = order[(step_off + i) % len(order)]
            zx, zy = int(cxs_arr[k]), int(cys_arr[k])
            if zone_clear(zx, zy):
                return (pick_tool(), zx, zy)
            checked += 1
            if checked > 100:
                break

    # ---- Services at population thresholds ----
    if obs.city_pop > 200:
        service_spots = [(20, 42), (55, 42), (90, 42), (20, 58), (55, 58), (90, 58)]
        for sx, sy in service_spots:
            if in_bounds(sx, sy) and bool(em[sy, sx]):
                return (Tool.FIRESTATION, sx, sy)

    if obs.city_pop > 500:
        police_spots = [(30, 45), (65, 45), (100, 45), (30, 55), (65, 55), (100, 55)]
        for sx, sy in police_spots:
            if in_bounds(sx, sy) and bool(em[sy, sx]):
                return (Tool.POLICESTATION, sx, sy)

    if obs.city_pop > 1000:
        # Add a 4th power plant (nuclear!) for the expanded city
        if in_bounds(60, 70) and not any(
            in_bounds(60+dx, 70+dy) and bool(pm[70+dy, 60+dx])
            for dy in range(-4,5) for dx in range(-4,5) if in_bounds(60+dx, 70+dy)
        ):
            return (Tool.NUCLEARPOWER, 60, 70)
        # Connect nuclear plant with wire
        for y in range(56, 69):
            if in_bounds(60, y) and bool(em[y, 60]) and not bool(pm[y, 60]):
                return (Tool.WIRE, 60, y)
        for x in range(50, 70):
            if in_bounds(x, 70) and bool(em[70, x]) and not bool(pm[70, x]):
                return (Tool.ROAD, x, 70)

    if obs.city_pop > 1500:
        # Stadium for extra commercial boost
        if in_bounds(45, 35) and bool(em[35, 45]):
            return (Tool.STADIUM, 45, 35)

    # ---- Extend roads as fallback ----
    road_ys2, road_xs2 = np.where(rm)
    if len(road_xs2) > 0:
        step_k = int(obs.step * 11) % max(len(road_xs2), 1)
        for offset in range(min(len(road_xs2), 30)):
            k = (step_k + offset * 7) % len(road_xs2)
            rx2, ry2 = int(road_xs2[k]), int(road_ys2[k])
            for dx2, dy2 in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                nx2, ny2 = rx2 + dx2, ry2 + dy2
                if in_bounds(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]) and bool(nbr_wire[ny2, nx2]):
                    return (Tool.ROAD, nx2, ny2)

    # ---- Expand wire as last fallback ----
    wire_ys_arr, wire_xs_arr = np.where(wm)
    if len(wire_xs_arr) > 0:
        step_k2 = int(obs.step * 13) % max(len(wire_xs_arr), 1)
        for offset in range(min(len(wire_xs_arr), 20)):
            k = (step_k2 + offset * 5) % len(wire_xs_arr)
            wx2, wy2 = int(wire_xs_arr[k]), int(wire_ys_arr[k])
            for dx3, dy3 in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                nx3, ny3 = wx2 + dx3, wy2 + dy3
                if in_bounds(nx3, ny3) and bool(em[ny3, nx3]) and not bool(pm[ny3, nx3]):
                    return (Tool.WIRE, nx3, ny3)

    return None

def init(obs, state):
    """Bootstrap: plant + wire spine seed + road seeds for two neighborhoods"""
    actions = []
    # Primary coal plant
    actions.append((Tool.COALPOWER, 30, 50))
    # Seed wire spine right of plant
    for y in range(47, 54):
        actions.append((Tool.WIRE, 33, y))
    # Seed roads flanking spine
    for y in range(47, 54):
        actions.append((Tool.ROAD, 32, y))
        actions.append((Tool.ROAD, 34, y))
    # Secondary plant far right
    actions.append((Tool.COALPOWER, 85, 50))
    # Seed wire spine right of second plant
    for y in range(47, 54):
        actions.append((Tool.WIRE, 88, y))
    # Roads flanking second spine
    for y in range(47, 54):
        actions.append((Tool.ROAD, 87, y))
        actions.append((Tool.ROAD, 89, y))
    return actions


def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    pop = obs.city_pop
    step = obs.step
    total_steps = obs.n_steps

    def in_b(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    def safe_empty(x, y):
        return in_b(x, y) and bool(em[y, x]) and not bool(pm[y, x])

    # ---- Infrastructure anchors ----
    # We maintain two "neighborhoods" centered around two power plants
    # Plant A near (30,50), Plant B near (85,50)
    # Each has a wire spine and flanking roads, then zones fill in

    # Ensure primary plant exists
    if not np.any(pm):
        return (Tool.COALPOWER, 30, 50)

    plant_ys, plant_xs = np.where(pm)
    plants = list(zip(plant_xs.tolist(), plant_ys.tolist()))

    # Define neighborhood configs: (plant_x, plant_y, wire_col, road_l, road_r)
    neighborhoods = [
        (30, 50, 33, 32, 34),
        (85, 50, 88, 87, 89),
    ]

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = res_count + com_count + ind_count

    # Zone ratio picker
    def pick_tool():
        t = max(total_zones, 1)
        ir = ind_count / t
        cr = com_count / t
        if ir < 0.20:
            return Tool.INDUSTRIAL
        if cr < 0.28:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    # ---- Ensure second plant placed ----
    if len(plants) < 2 and (total_zones > 5 or pop > 100):
        p2x, p2y = 85, 50
        if safe_empty(p2x, p2y):
            return (Tool.COALPOWER, p2x, p2y)

    # ---- Third plant for large cities ----
    if len(plants) < 3 and pop > 600:
        p3x, p3y = 57, 30
        if safe_empty(p3x, p3y):
            return (Tool.COALPOWER, p3x, p3y)
        # Add third neighborhood config

    # ---- Fourth plant ----
    if len(plants) < 4 and pop > 1500:
        p4x, p4y = 57, 70
        if safe_empty(p4x, p4y):
            return (Tool.COALPOWER, p4x, p4y)

    # Extend neighborhood configs based on pop
    if pop > 600:
        neighborhoods.append((57, 30, 60, 59, 61))
    if pop > 1500:
        neighborhoods.append((57, 70, 60, 59, 61))

    # ---- Wire spine management for each neighborhood ----
    # Spine grows vertically based on city needs
    pop_factor = min(40, pop // 10)
    spine_top_base = 5
    spine_bot_base = min(WORLD_H - 6, 95)

    for (px, py, wcol, rl, rr) in neighborhoods:
        # Only manage if plant actually exists nearby
        plant_near = any(
            in_b(px + dx, py + dy) and bool(pm[py + dy, px + dx])
            for dy in range(-3, 4) for dx in range(-3, 4)
            if in_b(px + dx, py + dy)
        )
        if not plant_near:
            continue

        spine_top = max(spine_top_base, py - 20 - pop_factor // 2)
        spine_bot = min(spine_bot_base, py + 20 + pop_factor // 2)

        # Find current wire extent in this column
        wire_rows = [r for r in range(WORLD_H) if in_b(wcol, r) and bool(wm[r, wcol])]

        if not wire_rows:
            # Seed wire adjacent to plant
            for dy in range(-2, 3):
                ny = py + dy
                if in_b(wcol, ny) and (bool(em[ny, wcol]) or bool(wm[ny, wcol])) and not bool(pm[ny, wcol]):
                    return (Tool.WIRE, wcol, ny)
        else:
            min_wr = min(wire_rows)
            max_wr = max(wire_rows)
            # Grow downward first
            if max_wr < spine_bot:
                nr = max_wr + 1
                if in_b(wcol, nr) and (bool(em[nr, wcol]) or bool(wm[nr, wcol])) and not bool(pm[nr, wcol]):
                    return (Tool.WIRE, wcol, nr)
            # Grow upward
            if min_wr > spine_top:
                nr = min_wr - 1
                if in_b(wcol, nr) and (bool(em[nr, wcol]) or bool(wm[nr, wcol])) and not bool(pm[nr, wcol]):
                    return (Tool.WIRE, wcol, nr)

            # Build roads flanking wire spine
            off = step % 4
            for wr in wire_rows[off::4]:
                for rc in [rl, rr]:
                    if in_b(rc, wr) and bool(em[wr, rc]) and not bool(pm[wr, rc]):
                        return (Tool.ROAD, rc, wr)

    # ---- Connect neighborhoods with horizontal wire bridges ----
    # Bridge at row py between neighborhoods
    if len(plants) >= 2 and pop > 50:
        bridge_y = 50
        # Bridge between first two neighborhoods wire cols
        wc1, wc2 = 33, 88
        # Find gaps in wire along bridge_y
        for bx in range(wc1, wc2 + 1):
            if in_b(bx, bridge_y) and bool(em[bridge_y, bx]) and not bool(pm[bridge_y, bx]):
                # Only bridge if we need connectivity
                left_has_wire = any(bool(wm[bridge_y, x]) for x in range(max(0, bx - 3), bx))
                right_has_wire = any(bool(wm[bridge_y, x]) for x in range(bx + 1, min(WORLD_W, bx + 4)))
                if left_has_wire or right_has_wire:
                    # Check if this row segment is incomplete
                    segment_complete = all(
                        bool(wm[bridge_y, x]) or bool(pm[bridge_y, x])
                        for x in range(wc1, wc2 + 1)
                    )
                    if not segment_complete:
                        return (Tool.WIRE, bx, bridge_y)
                    break

    # ---- Horizontal road connections between neighborhoods ----
    if pop > 150:
        hroad_y = 45  # horizontal road above bridge
        for rx in range(30, 92):
            if in_b(rx, hroad_y) and bool(em[hroad_y, rx]) and not bool(pm[hroad_y, rx]):
                # Only if adjacent to existing road or on path
                adj_road = any(
                    in_b(rx + dx, hroad_y + dy) and bool(rm[hroad_y + dy, rx + dx])
                    for dx, dy in [(1, 0), (-1, 0), (0, 1), (0, -1)]
                )
                if adj_road:
                    return (Tool.ROAD, rx, hroad_y)

    # ---- Add lateral road spurs for zone access ----
    # For each neighborhood, add horizontal roads every 6 rows
    if pop > 80:
        for (px, py, wcol, rl, rr) in neighborhoods:
            plant_near = any(
                in_b(px + dx, py + dy) and bool(pm[py + dy, px + dx])
                for dy in range(-3, 4) for dx in range(-3, 4)
                if in_b(px + dx, py + dy)
            )
            if not plant_near:
                continue
            wire_rows = [r for r in range(WORLD_H) if in_b(wcol, r) and bool(wm[r, wcol])]
            if not wire_rows:
                continue
            # Every 6th wire row, extend roads outward
            for wr in wire_rows[::6]:
                # Extend roads left and right from rl and rr
                for direction, start_col in [(-1, rl), (1, rr)]:
                    for dist in range(1, 8):
                        ex = start_col + direction * dist
                        if not in_b(ex, wr):
                            break
                        if bool(pm[wr, ex]):
                            break
                        if bool(rm[wr, ex]):
                            continue
                        if bool(em[wr, ex]):
                            # Only extend if adjacent to existing road
                            prev = start_col + direction * (dist - 1)
                            if bool(rm[wr, prev]) or bool(rm[wr, start_col]):
                                return (Tool.ROAD, ex, wr)
                            break

    # ---- Zone placement ----
    # Build proximity masks
    nbr_road = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-2, 3):
        for dx in range(-2, 3):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
            nbr_road[r0:r1, c0:c1] |= rm[sr0:sr1, sc0:sc1]

    nbr_wire = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-5, 6):
        for dx in range(-5, 6):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
            nbr_wire[r0:r1, c0:c1] |= wm[sr0:sr1, sc0:sc1]
            nbr_wire[r0:r1, c0:c1] |= pm[sr0:sr1, sc0:sc1]

    zone_tiles = resm | comm | indm

    def zone_clear(zx, zy):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                nr2, nc2 = zy + dr, zx + dc
                if not in_b(nc2, nr2):
                    return False
                if not bool(em[nr2, nc2]) and not bool(zone_tiles[nr2, nc2]):
                    return False
        return True

    cand_mask = em & nbr_road & nbr_wire
    # Buffer from edges
    cand_mask[0:3, :] = False
    cand_mask[WORLD_H-3:, :] = False
    cand_mask[:, 0:3] = False
    cand_mask[:, WORLD_W-3:] = False

    cys, cxs = np.where(cand_mask)
    if len(cxs) > 0:
        # Use first neighborhood plant as reference for distance ordering
        ref_x, ref_y = 57, 50  # center of map
        dists = np.abs(cxs - ref_x) * 0.5 + np.abs(cys - ref_y)
        order = np.argsort(dists)
        step_off = int(step * 7) % max(len(order), 1)
        checked = 0
        for i in range(len(order)):
            k = order[(step_off + i) % len(order)]
            zx, zy = int(cxs[k]), int(cys[k])
            if zone_clear(zx, zy):
                return (pick_tool(), zx, zy)
            checked += 1
            if checked > 100:
                break

    # ---- Extend roads near existing roads (gap fill) ----
    road_ys2, road_xs2 = np.where(rm)
    if len(road_xs2) > 0:
        step_k = int(step * 11) % max(len(road_xs2), 1)
        for offset in range(min(len(road_xs2), 30)):
            k = (step_k + offset * 7) % len(road_xs2)
            rx2, ry2 = int(road_xs2[k]), int(road_ys2[k])
            for dx2, dy2 in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                nx2, ny2 = rx2 + dx2, ry2 + dy2
                if in_b(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]) and bool(nbr_wire[ny2, nx2]):
                    return (Tool.ROAD, nx2, ny2)

    # ---- Services ----
    if pop > 120:
        for fpos in [(22, 42), (42, 42), (78, 42), (96, 42)]:
            fsx, fsy = fpos
            if in_b(fsx, fsy) and bool(em[fsy, fsx]):
                return (Tool.FIRESTATION, fsx, fsy)
    if pop > 300:
        for ppos in [(22, 58), (42, 58), (78, 58), (96, 58)]:
            psx, psy = ppos
            if in_b(psx, psy) and bool(em[psy, psx]):
                return (Tool.POLICESTATION, psx, psy)
    if pop > 800:
        for spos in [(57, 20), (57, 78)]:
            sx, sy = spos
            if in_b(sx, sy) and bool(em[sy, sx]):
                return (Tool.STADIUM, sx, sy)
    if pop > 1200:
        # Seaport and airport for big cities
        for apos in [(100, 20)]:
            ax, ay = apos
            if in_b(ax, ay) and bool(em[ay, ax]):
                return (Tool.AIRPORT, ax, ay)

    # ---- Expand wire laterally as fallback ----
    wire_ys_arr, wire_xs_arr = np.where(wm)
    if len(wire_xs_arr) > 0:
        step_k2 = int(step * 13) % max(len(wire_xs_arr), 1)
        for offset in range(min(len(wire_xs_arr), 20)):
            k = (step_k2 + offset * 5) % len(wire_xs_arr)
            wx2, wy2 = int(wire_xs_arr[k]), int(wire_ys_arr[k])
            for dx3, dy3 in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                nx3, ny3 = wx2 + dx3, wy2 + dy3
                if in_b(nx3, ny3) and bool(em[ny3, nx3]) and not bool(pm[ny3, nx3]):
                    return (Tool.WIRE, nx3, ny3)

    return None

def init(obs, state):
    """Bootstrap multiple anchor plants and seed wires/roads."""
    actions = []
    # Three primary plants at center row
    for px, py in [(30, 50), (60, 50), (90, 50)]:
        actions.append((Tool.COALPOWER, px, py))
        wc = px + 2
        for dy in range(-3, 4):
            actions.append((Tool.WIRE, wc, py + dy))
        for dy in range(-3, 4):
            actions.append((Tool.ROAD, wc - 1, py + dy))
            actions.append((Tool.ROAD, wc + 1, py + dy))
    return actions


def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    pop = obs.city_pop
    step = obs.step

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = res_count + com_count + ind_count

    # ---- ANCHOR DEFINITIONS ----
    # Each anchor: (plant_x, plant_y, wire_col, road_l, road_r)
    # 9 anchors covering the map in a 3x3 grid
    all_anchors = [
        (30, 50, 32, 31, 33),
        (60, 50, 62, 61, 63),
        (90, 50, 92, 91, 93),
        (30, 25, 32, 31, 33),
        (60, 25, 62, 61, 63),
        (90, 25, 92, 91, 93),
        (30, 75, 32, 31, 33),
        (60, 75, 62, 61, 63),
        (90, 75, 92, 91, 93),
        # Extra anchors for very large cities
        (15, 50, 17, 16, 18),
        (105, 50, 107, 106, 108),
        (15, 25, 17, 16, 18),
        (105, 25, 107, 106, 108),
        (15, 75, 17, 16, 18),
        (105, 75, 107, 106, 108),
    ]

    def num_active_anchors():
        if pop < 50:
            return 1
        elif pop < 200:
            return 2
        elif pop < 500:
            return 3
        elif pop < 1000:
            return 5
        elif pop < 2000:
            return 7
        elif pop < 4000:
            return 9
        else:
            return 12

    active_anchors = all_anchors[:num_active_anchors()]

    # ---- ENSURE POWER PLANTS ----
    for (px, py, wc, rl, rr) in active_anchors:
        has_plant = any(
            ib(px + dx, py + dy) and bool(pm[py + dy, px + dx])
            for dx in range(-4, 5) for dy in range(-4, 5)
            if ib(px + dx, py + dy)
        )
        if not has_plant:
            if ib(px, py) and bool(em[py, px]):
                return (Tool.COALPOWER, px, py)
            for r in range(1, 10):
                for dy2 in range(-r, r + 1):
                    for dx2 in range(-r, r + 1):
                        nx, ny = px + dx2, py + dy2
                        if ib(nx, ny) and bool(em[ny, nx]):
                            return (Tool.COALPOWER, nx, ny)

    # ---- WIRE SPINE BUILDING ----
    pop_factor = min(40, pop // 8)
    for (px, py, wc, rl, rr) in active_anchors:
        if not ib(wc, py):
            continue
        spine_top = max(2, py - 18 - pop_factor)
        spine_bot = min(WORLD_H - 3, py + 18 + pop_factor)

        wire_in_col = [r for r in range(WORLD_H) if ib(wc, r) and bool(wm[r, wc])]

        if not wire_in_col:
            for dy2 in range(-4, 5):
                ny = py + dy2
                if ib(wc, ny) and bool(em[ny, wc]) and not bool(pm[ny, wc]):
                    return (Tool.WIRE, wc, ny)
        else:
            min_wr = min(wire_in_col)
            max_wr = max(wire_in_col)
            if max_wr < spine_bot:
                nr = max_wr + 1
                if ib(wc, nr) and not bool(pm[nr, wc]):
                    return (Tool.WIRE, wc, nr)
            if min_wr > spine_top:
                nr = min_wr - 1
                if ib(wc, nr) and not bool(pm[nr, wc]):
                    return (Tool.WIRE, wc, nr)

    # ---- HORIZONTAL WIRE CONNECTIONS between same-row anchors ----
    for i in range(len(active_anchors) - 1):
        px1, py1, wc1, _, _ = active_anchors[i]
        px2, py2, wc2, _, _ = active_anchors[i + 1]
        if abs(py1 - py2) <= 5:  # Same row anchors
            conn_y = min(py1, py2)
            min_wc = min(wc1, wc2) + 1
            max_wc = max(wc1, wc2)
            for cx in range(min_wc, max_wc):
                if ib(cx, conn_y) and bool(em[conn_y, cx]) and not bool(pm[conn_y, cx]):
                    return (Tool.WIRE, cx, conn_y)

    # ---- ROAD BUILDING flanking wire spines ----
    for (px, py, wc, rl, rr) in active_anchors:
        wire_in_col = [r for r in range(WORLD_H) if ib(wc, r) and bool(wm[r, wc])]
        if not wire_in_col:
            continue
        cycle = step % 4
        for wr in wire_in_col[cycle::4]:
            if ib(rl, wr) and bool(em[wr, rl]) and not bool(pm[wr, rl]):
                return (Tool.ROAD, rl, wr)
            if ib(rr, wr) and bool(em[wr, rr]) and not bool(pm[wr, rr]):
                return (Tool.ROAD, rr, wr)

    # ---- ZONE PLACEMENT ----
    zone_tiles = resm | comm | indm

    def pick_tool():
        t = max(total_zones, 1)
        i_r = ind_count / t
        c_r = com_count / t
        if i_r < 0.22:
            return Tool.INDUSTRIAL
        if c_r < 0.25:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    def zone_clear(zx, zy):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                nr2, nc2 = zy + dr, zx + dc
                if not ib(nc2, nr2):
                    return False
                if not bool(em[nr2, nc2]) and not bool(zone_tiles[nr2, nc2]):
                    return False
        return True

    # Compute neighbor road and wire masks efficiently
    nbr_road = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy2 in range(-2, 3):
        for dx2 in range(-2, 3):
            sr0 = max(0, -dy2); sr1 = min(WORLD_H, WORLD_H - dy2)
            sc0 = max(0, -dx2); sc1 = min(WORLD_W, WORLD_W - dx2)
            r0 = max(0, dy2); r1 = min(WORLD_H, WORLD_H + dy2)
            c0 = max(0, dx2); c1 = min(WORLD_W, WORLD_W + dx2)
            nbr_road[r0:r1, c0:c1] |= rm[sr0:sr1, sc0:sc1]

    nbr_wire = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy2 in range(-8, 9):
        for dx2 in range(-8, 9):
            sr0 = max(0, -dy2); sr1 = min(WORLD_H, WORLD_H - dy2)
            sc0 = max(0, -dx2); sc1 = min(WORLD_W, WORLD_W - dx2)
            r0 = max(0, dy2); r1 = min(WORLD_H, WORLD_H + dy2)
            c0 = max(0, dx2); c1 = min(WORLD_W, WORLD_W + dx2)
            nbr_wire[r0:r1, c0:c1] |= wm[sr0:sr1, sc0:sc1]
            nbr_wire[r0:r1, c0:c1] |= pm[sr0:sr1, sc0:sc1]

    cand_mask = em & nbr_road & nbr_wire
    cand_mask[0:2, :] = False
    cand_mask[WORLD_H - 2:, :] = False
    cand_mask[:, 0:2] = False
    cand_mask[:, WORLD_W - 2:] = False

    cys, cxs = np.where(cand_mask)
    if len(cxs) > 0:
        # Prioritize candidates near active anchor wire columns
        best_dist = np.full(len(cxs), 999999, dtype=float)
        for (px, py, wc, rl, rr) in active_anchors:
            d = np.abs(cxs - wc) + np.abs(cys - py) * 0.7
            best_dist = np.minimum(best_dist, d)
        order = np.argsort(best_dist)
        step_off = (step * 7) % max(len(order), 1)
        checked = 0
        for i in range(len(order)):
            k = order[(step_off + i) % len(order)]
            zx, zy = int(cxs[k]), int(cys[k])
            if zone_clear(zx, zy):
                return (pick_tool(), zx, zy)
            checked += 1
            if checked > 120:
                break

    # ---- EXTEND ROADS from existing roads near wire ----
    road_ys2, road_xs2 = np.where(rm)
    if len(road_xs2) > 0:
        step_k = (step * 11) % max(len(road_xs2), 1)
        for offset in range(min(len(road_xs2), 40)):
            k = (step_k + offset * 7) % len(road_xs2)
            rx2, ry2 = int(road_xs2[k]), int(road_ys2[k])
            for dx2, dy2 in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                nx2, ny2 = rx2 + dx2, ry2 + dy2
                if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]) and bool(nbr_wire[ny2, nx2]):
                    return (Tool.ROAD, nx2, ny2)

    # ---- CIVIC SERVICES based on population ----
    if pop > 200:
        fire_spots = [
            (45, 50), (75, 50), (45, 25), (75, 25),
            (45, 75), (75, 75), (20, 50), (100, 50),
            (20, 25), (100, 25), (20, 75), (100, 75),
        ]
        for (sx, sy) in fire_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.FIRESTATION, sx, sy)

    if pop > 600:
        police_spots = [
            (45, 38), (75, 38), (45, 62), (75, 62),
            (20, 38), (100, 38), (20, 62), (100, 62),
            (55, 50), (55, 25), (55, 75),
        ]
        for (sx, sy) in police_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.POLICESTATION, sx, sy)

    if pop > 1500:
        for (sx, sy) in [(55, 15), (55, 85), (15, 50), (105, 50), (55, 50)]:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.STADIUM, sx, sy)

    if pop > 3000:
        for (sx, sy) in [(55, 10), (55, 90), (10, 50), (110, 50)]:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.AIRPORT, sx, sy)

    # ---- FALLBACK: extend wire laterally ----
    wire_ys_arr, wire_xs_arr = np.where(wm)
    if len(wire_xs_arr) > 0:
        step_k2 = (step * 13) % max(len(wire_xs_arr), 1)
        for offset in range(min(len(wire_xs_arr), 25)):
            k = (step_k2 + offset * 5) % len(wire_xs_arr)
            wx2, wy2 = int(wire_xs_arr[k]), int(wire_ys_arr[k])
            for dx3, dy3 in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                nx3, ny3 = wx2 + dx3, wy2 + dy3
                if ib(nx3, ny3) and bool(em[ny3, nx3]) and not bool(pm[ny3, nx3]):
                    return (Tool.WIRE, nx3, ny3)

    return None

# Ambitious multi-cluster city policy
# Strategy: 4 power plants in a grid pattern, horizontal road spines,
# dense zone packing between roads, progressive expansion

def init(obs, state):
    """Bootstrap: plant + wire + road seed at primary cluster."""
    actions = []
    # Primary coal plant
    actions.append((Tool.COALPOWER, 20, 50))
    # Wire spine right from plant
    for dx in range(1, 6):
        actions.append((Tool.WIRE, 20 + dx, 50))
    # Horizontal roads above and below wire
    for dx in range(1, 6):
        actions.append((Tool.ROAD, 20 + dx, 48))
        actions.append((Tool.ROAD, 20 + dx, 52))
    return actions


def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    pop = obs.city_pop
    step = obs.step

    def ib(x, y):
        return 2 <= x < WORLD_W - 2 and 2 <= y < WORLD_H - 2

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = res_count + com_count + ind_count

    # --- CLUSTER DEFINITIONS ---
    # Each cluster: (plant_x, plant_y, road_y_top, road_y_bot, x_start, x_end)
    # Horizontal layout: wire along plant row, roads above/below, zones between
    clusters = [
        # (plant_x, plant_y, wire_y, road_top, road_bot, zone_x_start, zone_x_end, id)
        (20, 50, 50, 47, 53, 22, 45, 0),   # left-center
        (65, 50, 50, 47, 53, 55, 85, 1),   # center
        (20, 25, 25, 22, 28, 22, 45, 2),   # left-top
        (65, 25, 25, 22, 28, 55, 85, 3),   # center-top
        (20, 75, 75, 72, 78, 22, 45, 4),   # left-bottom
        (65, 75, 75, 72, 78, 55, 85, 5),   # center-bottom
        (100, 50, 50, 47, 53, 88, 115, 6), # right-center
        (100, 25, 25, 22, 28, 88, 115, 7), # right-top
        (100, 75, 75, 72, 78, 88, 115, 8), # right-bottom
    ]

    # Progressive unlock based on population
    def num_clusters():
        if pop < 50:   return 1
        if pop < 200:  return 2
        if pop < 500:  return 3
        if pop < 900:  return 4
        if pop < 1500: return 5
        if pop < 2500: return 6
        if pop < 4000: return 7
        if pop < 6000: return 8
        return 9

    active = clusters[:num_clusters()]

    # --- ENSURE POWER PLANTS ---
    for (px, py, wy, rt, rb, xs, xe, cid) in active:
        # Check 5x5 around plant location
        has_plant = False
        for dy in range(-2, 3):
            for dx in range(-2, 3):
                nx, ny = px + dx, py + dy
                if 0 <= nx < WORLD_W and 0 <= ny < WORLD_H:
                    if bool(pm[ny, nx]):
                        has_plant = True
        if not has_plant:
            if ib(px, py):
                return (Tool.COALPOWER, px, py)

    # --- BUILD HORIZONTAL WIRE SPINES ---
    for (px, py, wy, rt, rb, xs, xe, cid) in active:
        # Wire from plant to right edge of cluster zone
        for wx in range(px + 2, xe + 1):
            if not ib(wx, wy):
                continue
            if not bool(wm[wy, wx]) and not bool(pm[wy, wx]) and bool(em[wy, wx]):
                return (Tool.WIRE, wx, wy)
        # Wire from plant leftward to xs
        for wx in range(px - 1, xs - 1, -1):
            if not ib(wx, wy):
                continue
            if not bool(wm[wy, wx]) and not bool(pm[wy, wx]) and bool(em[wy, wx]):
                return (Tool.WIRE, wx, wy)

    # --- CONNECT CLUSTERS WITH HORIZONTAL WIRES at same Y ---
    # Connect clusters at same Y row
    row_groups = {}
    for (px, py, wy, rt, rb, xs, xe, cid) in active:
        if wy not in row_groups:
            row_groups[wy] = []
        row_groups[wy].append((px, py, wy, rt, rb, xs, xe, cid))

    for wy_key, group in row_groups.items():
        if len(group) < 2:
            continue
        group_sorted = sorted(group, key=lambda c: c[0])
        for i in range(len(group_sorted) - 1):
            px1 = group_sorted[i][0]
            px2 = group_sorted[i + 1][0]
            for cx in range(px1 + 3, px2):
                if ib(cx, wy_key) and bool(em[wy_key, cx]) and not bool(pm[wy_key, cx]):
                    return (Tool.WIRE, cx, wy_key)

    # --- BUILD HORIZONTAL ROADS ---
    for (px, py, wy, rt, rb, xs, xe, cid) in active:
        # Top road
        for rx in range(xs, xe + 1):
            if not ib(rx, rt):
                continue
            if bool(em[rt, rx]) and not bool(pm[rt, rx]):
                return (Tool.ROAD, rx, rt)
        # Bottom road
        for rx in range(xs, xe + 1):
            if not ib(rx, rb):
                continue
            if bool(em[rb, rx]) and not bool(pm[rb, rx]):
                return (Tool.ROAD, rx, rb)

    # --- ADD VERTICAL CONNECTOR ROADS between clusters at different Y ---
    # Connect top/bottom clusters vertically
    vert_connectors = [
        # (x_col, y_from, y_to)
        (30, 28, 47),   # left clusters top to center
        (30, 53, 72),   # left clusters center to bottom
        (70, 28, 47),   # center clusters
        (70, 53, 72),
        (105, 28, 47),  # right clusters
        (105, 53, 72),
    ]
    for (vcx, vcy1, vcy2) in vert_connectors:
        for vy in range(vcy1, vcy2 + 1):
            if not ib(vcx, vy):
                continue
            if bool(em[vy, vcx]) and not bool(pm[vy, vcx]) and not bool(wm[vy, vcx]):
                return (Tool.ROAD, vcx, vy)

    # --- ZONE PLACEMENT ---
    zone_tiles = resm | comm | indm

    def pick_tool():
        t = max(total_zones, 1)
        ir = ind_count / t
        cr = com_count / t
        if ir < 0.25:
            return Tool.INDUSTRIAL
        if cr < 0.30:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    def zone_clear(zx, zy):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                nr, nc = zy + dr, zx + dc
                if not (0 <= nc < WORLD_W and 0 <= nr < WORLD_H):
                    return False
                if not bool(em[nr, nc]) and not bool(zone_tiles[nr, nc]):
                    return False
        return True

    # Build neighbor road/wire accessibility maps
    nbr_road = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in [-1, 0, 1, -2, 2]:
        for dx in [-1, 0, 1, -2, 2]:
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
            nbr_road[r0:r1, c0:c1] |= rm[sr0:sr1, sc0:sc1]

    nbr_wire = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-6, 7):
        for dx in range(-6, 7):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
            nbr_wire[r0:r1, c0:c1] |= wm[sr0:sr1, sc0:sc1]
            nbr_wire[r0:r1, c0:c1] |= pm[sr0:sr1, sc0:sc1]

    cand_mask = em & nbr_road & nbr_wire
    # Keep away from edges
    cand_mask[0:3, :] = False
    cand_mask[WORLD_H - 3:, :] = False
    cand_mask[:, 0:3] = False
    cand_mask[:, WORLD_W - 3:] = False

    cys, cxs = np.where(cand_mask)
    if len(cxs) > 0:
        # Score by proximity to active cluster centers
        best_dist = np.full(len(cxs), 999999.0)
        for (px, py, wy, rt, rb, xs, xe, cid) in active:
            cx_mid = (xs + xe) // 2
            d = np.abs(cxs - cx_mid).astype(float) + np.abs(cys - wy).astype(float)
            best_dist = np.minimum(best_dist, d)

        order = np.argsort(best_dist)
        offset = (step * 7) % max(len(order), 1)
        checked = 0
        for i in range(len(order)):
            k = order[(offset + i) % len(order)]
            zx, zy = int(cxs[k]), int(cys[k])
            if zone_clear(zx, zy):
                return (pick_tool(), zx, zy)
            checked += 1
            if checked > 150:
                break

    # --- EXTEND ROADS from existing road network ---
    road_ys, road_xs = np.where(rm)
    if len(road_xs) > 0:
        step_k = (step * 11) % max(len(road_xs), 1)
        for off in range(min(len(road_xs), 40)):
            k = (step_k + off * 7) % len(road_xs)
            rx, ry = int(road_xs[k]), int(road_ys[k])
            for dx, dy in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                nx, ny = rx + dx, ry + dy
                if ib(nx, ny) and bool(em[ny, nx]) and not bool(pm[ny, nx]) and bool(nbr_wire[ny, nx]):
                    return (Tool.ROAD, nx, ny)

    # --- CIVIC SERVICES (closed-loop, based on pop) ---
    if pop > 200:
        fire_spots = [
            (35, 50), (80, 50), (35, 25), (80, 25),
            (35, 75), (80, 75), (110, 50), (110, 25), (110, 75)
        ]
        for (sx, sy) in fire_spots[:num_clusters()]:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.FIRESTATION, sx, sy)

    if pop > 600:
        police_spots = [
            (40, 50), (75, 50), (40, 25), (75, 25),
            (40, 75), (75, 75), (108, 38), (108, 62)
        ]
        for (sx, sy) in police_spots[:num_clusters()]:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.POLICESTATION, sx, sy)

    if pop > 1500:
        stadiums = [(50, 38), (50, 62), (85, 38), (85, 62)]
        for (sx, sy) in stadiums:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.STADIUM, sx, sy)

    if pop > 3000:
        # Seaport and airport for high-value commercial boost
        if ib(10, 90) and bool(em[90, 10]):
            return (Tool.SEAPORT, 10, 90)
        if ib(60, 90) and bool(em[90, 60]):
            return (Tool.AIRPORT, 60, 90)

    # --- FALLBACK: extend wire to power more areas ---
    wire_ys, wire_xs = np.where(wm)
    if len(wire_xs) > 0:
        step_k2 = (step * 13) % max(len(wire_xs), 1)
        for off in range(min(len(wire_xs), 30)):
            k = (step_k2 + off * 5) % len(wire_xs)
            wx2, wy2 = int(wire_xs[k]), int(wire_ys[k])
            for dx, dy in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                nx, ny = wx2 + dx, wy2 + dy
                if ib(nx, ny) and bool(em[ny, nx]) and not bool(pm[ny, nx]):
                    return (Tool.WIRE, nx, ny)

    return None

